        forall |ex: Execution<T>| #[trigger] always(p.and(q)).satisfied_by(ex) ==> {
            // Unfold `always(p)` to its definition: forall suffixes.
            forall |i: nat| #[trigger] p.satisfied_by(ex.suffix(i))
        }
