        forall |ex: Execution<T>| #[trigger] always(p.and(q)).satisfied_by(ex) ==> {
            forall |i: nat| #[trigger] q.satisfied_by(ex.suffix(i))
        }
    );

    // Combine the two implications into the required `always(p).and(always(q))`.
    assert(
        forall |ex: Execution<T>| #[trigger] always(p.and(q)).satisfied_by(ex) ==>
            always(p).and(always(q)).satisfied_by(ex)
    );
}

