proof fn always_distributed_by_and<T>(p: TempPred<T>, q: TempPred<T>)
    ensures valid(always(p.and(q)).implies(always(p).and(always(q))))
{
    // Expand the definitions of `always` and `TempPred::and::satisfied_by` and
    // prove that `forall i. (A(i) && B(i))` implies
    // `(forall i. A(i)) && (forall i. B(i))`.

    assert(
        forall |ex: Execution<T>| #[trigger] {
            always(p.and(q)).satisfied_by(ex) ==> forall |i: nat| #[trigger] p.satisfied_by(ex.suffix(i))
        }
    );

    assert(
        forall |ex: Execution<T>| #[trigger] {
            always(p.and(q)).satisfied_by(ex) ==> forall |i: nat| #[trigger] q.satisfied_by(ex.suffix(i))
        }
    );

    assert(
        forall |ex: Execution<T>| #[trigger] {
            always(p.and(q)).satisfied_by(ex) ==> {
                always(p).satisfied_by(ex) && always(q).satisfied_by(ex)
            }
        }
    );

    // `always(p).and(always(q)).satisfied_by(ex)` is exactly
    // `always(p).satisfied_by(ex) && always(q).satisfied_by(ex)`.
    assert(
        forall |ex: Execution<T>| #[trigger] {
            always(p.and(q)).satisfied_by(ex) ==> always(p).and(always(q)).satisfied_by(ex)
        }
    );

    // Finally, the desired postcondition is `valid` of an implication.
    assert(
        forall |ex: Execution<T>| #[trigger] {
            always(p.and(q)).satisfied_by(ex) ==> always(p).and(always(q)).satisfied_by(ex)
        }
    );
