proof fn always_distributed_by_and<T>(p: TempPred<T>, q: TempPred<T>)
    ensures valid(always(p.and(q)).implies(always(p).and(always(q))))
{
    forall |ex: Execution<T>| {
        if always(p.and(q)).satisfied_by(ex) {
            // From the definition of `always`, we can derive `p && q` at every suffix.
            forall |i: nat| {
                assert(p.and(q).satisfied_by(ex.suffix(i)));
                assert(p.satisfied_by(ex.suffix(i)));
                assert(q.satisfied_by(ex.suffix(i)));
            };

            // Now show `always(p)` and `always(q)` at `ex`.
            assert(always(p).satisfied_by(ex));
            assert(always(q).satisfied_by(ex));
        }
        // Therefore, the implication holds at `ex`.
        assert((always(p.and(q)).implies(always(p).and(always(q)))).satisfied_by(ex));
    };
}

