proof fn always_distributed_by_and<T>(p: TempPred<T>, q: TempPred<T>)
    ensures valid(always(p.and(q)).implies(always(p).and(always(q)))),
{
    assert(
        forall |ex: Execution<T>| #[trigger]
            always(p.and(q)).satisfied_by(ex) ==> {
                // Unfold the definitions of `always` and `and`.
                // From `always(p.and(q))`, for every suffix i we have p and q.
                forall |i: nat| #[trigger]
                    p.satisfied_by(ex.suffix(i));
                forall |i: nat| #[trigger]
                    q.satisfied_by(ex.suffix(i));

                always(p).and(always(q)).satisfied_by(ex)
            }
    );
}


